describe('Mobile Responsive Sauce Demo Store', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
  });

  it('should display inventory page on mobile portrait viewport with burger menu visible', () => {
    cy.viewport('375x812');
    cy.get('[data-test="login-container"]').should('be.visible');
    cy.get('[data-test="username"]').type('standard_user');
    cy.get('[data-test="password"]').type('secret_sauce');
    cy.get('[data-test="login-button"]').click();
    cy.get('#page_wrapper').should('contain', 'Inventory');
    cy.get('#react-burger-menu-btn').should('be.visible');
    cy.get('[data-test="open-menu"]').click();
    cy.get('[data-testid="bm-menu"]').should('be.visible');
    cy.get('[data-test="logout-sidebar-link"]').should('be.visible');
    cy.get('[data-test="close-menu"]').click();
    cy.get('#react-burger-cross-btn').should('be.visible');
  });

  it('should handle burger menu button click and close on mobile portrait viewport', () => {
    cy.viewport('375x812');
    cy.get('[data-test="login-container"]').should('be.visible');
    cy.get('[data-test="username"]').type('standard_user');
    cy.get('[data-test="password"]').type('secret_sauce');
    cy.get('[data-test="login-button"]').click();
    cy.get('#page_wrapper').should('contain', 'Inventory');
    cy.get('#react-burger-menu-btn').click();
    cy.get('[data-testid="bm-menu"]').should('be.visible');
    cy.get('[data-test="close-menu"]').click();
    cy.get('#react-burger-menu-btn').should('not.exist');
    cy.get('#page_wrapper').should('contain', 'Inventory');
  });
});
